CREATE TABLE "FinanceIncident" ("id" TEXT NOT NULL PRIMARY KEY, "reference" TEXT NOT NULL, "caseId" TEXT, "caseReference" TEXT NOT NULL DEFAULT '', "createdBy" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "implicatedPersonId" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "status" TEXT NOT NULL DEFAULT 'RECEIVED', "urgency" TEXT NOT NULL, "title" TEXT NOT NULL, "data" JSONB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "FinanceIncident_reference_key" ON "FinanceIncident"("reference");
CREATE INDEX "FinanceIncident_ownerId_status_idx" ON "FinanceIncident"("ownerId", "status");
CREATE TABLE "FinanceIncidentEvent" ("id" TEXT NOT NULL PRIMARY KEY, "incidentId" TEXT NOT NULL, "version" INTEGER NOT NULL, "actorId" TEXT NOT NULL, "actorName" TEXT NOT NULL, "action" TEXT NOT NULL, "reason" TEXT NOT NULL, "snapshot" JSONB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FinanceIncidentEvent_incidentId_fkey" FOREIGN KEY ("incidentId") REFERENCES "FinanceIncident"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "FinanceIncidentEvent_incidentId_version_key" ON "FinanceIncidentEvent"("incidentId", "version");
